import{_ as e,c as o,o as n,j as s,Y as a,t as d}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"sort | x-cmd man (man1) | sort lines of text files","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | sort - sort lines of text files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"sort | x-cmd man (man1) | sort lines of text files"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | sort - sort lines of text files"}]]},"headers":[],"params":{"isMan":true,"man":"sort","category":"man1","desc":"sort lines of text files"},"relativePath":"man1/sort.md","filePath":"man1/[man].md"}'),i={name:"man1/sort.md"},g={class:"visually-hidden"};function l(r,t,m,c,h,p){return n(),o("div",null,[s("h1",g,d(r.$params.man),1),t[0]||(t[0]=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>sort - sort lines of text files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>sort</strong> [<em>OPTION</em>]... [<em>FILE</em>]... <br> <strong>sort</strong> [<em>OPTION</em>]... <em>--files0-from=F</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Write sorted concatenation of all FILE(s) to standard output.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>Mandatory arguments to long options are mandatory for short options too. Ordering options:</p><dl><dt><strong>-b</strong>, <strong>--ignore-leading-blanks</strong></dt><dd>ignore leading blanks</dd><dt><strong>-d</strong>, <strong>--dictionary-order</strong></dt><dd>consider only blanks and alphanumeric characters</dd><dt><strong>-f</strong>, <strong>--ignore-case</strong></dt><dd>fold lower case to upper case characters</dd><dt><strong>-g</strong>, <strong>--general-numeric-sort</strong></dt><dd>compare according to general numerical value</dd><dt><strong>-i</strong>, <strong>--ignore-nonprinting</strong></dt><dd>consider only printable characters</dd><dt><strong>-M</strong>, <strong>--month-sort</strong></dt><dd>compare (unknown) &lt; &#39;JAN&#39; &lt; ... &lt; &#39;DEC&#39;</dd><dt><strong>-h</strong>, <strong>--human-numeric-sort</strong></dt><dd>compare human readable numbers (e.g., 2K 1G)</dd><dt><strong>-n</strong>, <strong>--numeric-sort</strong></dt><dd>compare according to string numerical value</dd><dt><strong>-R</strong>, <strong>--random-sort</strong></dt><dd>shuffle, but group identical keys. See <strong>shuf</strong>(1)</dd><dt><strong>--random-source</strong>=<em>FILE</em></dt><dd>get random bytes from FILE</dd><dt><strong>-r</strong>, <strong>--reverse</strong></dt><dd>reverse the result of comparisons</dd><dt><strong>--sort</strong>=<em>WORD</em></dt><dd>sort according to WORD: general-numeric <strong>-g</strong>, human-numeric <strong>-h</strong>, month <strong>-M</strong>, numeric <strong>-n</strong>, random <strong>-R</strong>, version <strong>-V</strong></dd><dt><strong>-V</strong>, <strong>--version-sort</strong></dt><dd>natural sort of (version) numbers within text</dd></dl><p>Other options:</p><dl><dt><strong>--batch-size</strong>=<em>NMERGE</em></dt><dd>merge at most NMERGE inputs at once; for more use temp files</dd><dt><strong>-c</strong>, <strong>--check</strong>, <strong>--check</strong>=<em>diagnose-first</em></dt><dd>check for sorted input; do not sort</dd><dt><strong>-C</strong>, <strong>--check</strong>=<em>quiet</em>, <strong>--check</strong>=<em>silent</em></dt><dd>like <strong>-c</strong>, but do not report first bad line</dd><dt><strong>--compress-program</strong>=<em>PROG</em></dt><dd>compress temporaries with PROG; decompress them with PROG <strong>-d</strong></dd><dt><strong>--debug</strong></dt><dd>annotate the part of the line used to sort, and warn about questionable usage to stderr</dd><dt><strong>--files0-from</strong>=<em>F</em></dt><dd>read input from the files specified by NUL-terminated names in file F; If F is - then read names from standard input</dd><dt><strong>-k</strong>, <strong>--key</strong>=<em>KEYDEF</em></dt><dd>sort via a key; KEYDEF gives location and type</dd><dt><strong>-m</strong>, <strong>--merge</strong></dt><dd>merge already sorted files; do not sort</dd><dt><strong>-o</strong>, <strong>--output</strong>=<em>FILE</em></dt><dd>write result to FILE instead of standard output</dd><dt><strong>-s</strong>, <strong>--stable</strong></dt><dd>stabilize sort by disabling last-resort comparison</dd><dt><strong>-S</strong>, <strong>--buffer-size</strong>=<em>SIZE</em></dt><dd>use SIZE for main memory buffer</dd><dt><strong>-t</strong>, <strong>--field-separator</strong>=<em>SEP</em></dt><dd>use SEP instead of non-blank to blank transition</dd><dt><strong>-T</strong>, <strong>--temporary-directory</strong>=<em>DIR</em></dt><dd>use DIR for temporaries, not $TMPDIR or <em>/tmp</em>; multiple options specify multiple directories</dd><dt><strong>--parallel</strong>=<em>N</em></dt><dd>change the number of sorts run concurrently to N</dd><dt><strong>-u</strong>, <strong>--unique</strong></dt><dd>with <strong>-c</strong>, check for strict ordering; without <strong>-c</strong>, output only the first of an equal run</dd><dt><strong>-z</strong>, <strong>--zero-terminated</strong></dt><dd>line delimiter is NUL, not newline</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>KEYDEF is F[.C][OPTS][,F[.C][OPTS]] for start and stop position, where F is a field number and C a character position in the field; both are origin 1, and the stop position defaults to the line&#39;s end. If neither <strong>-t</strong> nor <strong>-b</strong> is in effect, characters in a field are counted from the beginning of the preceding whitespace. OPTS is one or more single-letter ordering options [bdfgiMhnRrV], which override global ordering options for that key. If no key is given, use the entire line as the key. Use <strong>--debug</strong> to diagnose incorrect key usage.</p><p>SIZE may be followed by the following multiplicative suffixes: % 1% of memory, b 1, K 1024 (default), and so on for M, G, T, P, E, Z, Y, R, Q.</p><p>*** WARNING *** The locale specified by the environment affects sort order. Set LC_ALL=C to get the traditional sort order that uses native byte values.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Mike Haertel and Paul Eggert.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>shuf</strong>(1), <strong>uniq</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/sort%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/sort\\</a>&gt; <br> or available locally via: info &#39;(coreutils) sort invocation&#39;</p>',23))])}const b=e(i,[["render",l]]);export{f as __pageData,b as default};
